            {
                if (_userProfileResolver is null) return m;
                var profile = await _userProfileResolver
                    .GetProfileAsync(m.UserId)
                    .ConfigureAwait(true);
                return m with
                {
                    DisplayName = profile?.DisplayName ?? m.DisplayName,
                    AvatarUrl = profile?.AvatarUrl ?? m.AvatarUrl
                };
            })).ConfigureAwait

